inline constexpr std::size_t kCatalogCount = sizeof(kCatalog) / sizeof(kCatalog[0]);

inline constexpr const char* name(Icon icon) {
    for (std::size_t i = 0; i < kCatalogCount; ++i) {
        if (kCatalog[i].icon == icon)
            return kCatalog[i].name;
    }
    return "";
}

